a<-commandArgs(FALSE);here<-dirname(normalizePath(sub("^--file=","",a[grepl("^--file=",a)][1])))
source(file.path(here,"../scripts/fig_all.R"))
out<-Sys.getenv("OMICSTAT_SEMANTICS_TEST_OUT",file.path(tempdir(),"figure-semantics"));dir.create(out,recursive=TRUE,showWarnings=FALSE)
failures<-character();checks<-0L
check<-function(x,label){checks<<-checks+1L;if(isTRUE(x))cat("PASS:",label,"\n")else{cat("FAIL:",label,"\n");failures<<-c(failures,label)}}
bad<-function(expr,label){e<-tryCatch({force(expr);NULL},error=conditionMessage);check(!is.null(e)&&grepl("OS_",e,fixed=TRUE),label)}
raw<-data.frame(id=c("z","a","q"),person=c("P1","P2","P1"),value=c(.2,.3,NA),flag=c(TRUE,FALSE,TRUE))
lay<-os_semantic_layer("observations",raw,"id","observed","probability","fraction",raw$person,"people",population_id="synthetic")
st<-os_statistic_contract("raw",c(0,.053,NA),raw$id,"raw_p",method="supplied t",adjustment="none",family_id="three",family_size=3,threshold=.05)
pop<-list(status="known",ids=as.list(raw$id),rule="all invented rows")
def<-os_figure_definition("probability","visit","people","fraction",pop,pop,"none",list(lay),statistics=list(st))
check(lay$n_rows==3&&lay$n_independent==2,"repeated visits are three observations/two people")
check(st$decision$q=="unknown"&&st$decision$a=="not_below_threshold","missing and P=.053 never become significant")
check(identical(os_semantic_table_sha256(raw,raw$id),os_semantic_table_sha256(raw[3:1,4:1],rev(raw$id))),"source hash ignores row/column display order")
bad(os_semantic_layer("bad",data.frame(id=c(1,2)),"id","observed","x","unknown"),"numeric labels not silently treated as IDs")
bad(os_semantic_layer("bad",raw[c(1,1),],"id","observed","x","unknown"),"duplicate source keys refused")
for(field in c("n_observations","n_independent")) {d<-def;d$layers[[1]][[field]]<-999;bad(os_validate_figure_definition(d),paste("tampered",field,"refused"))}
d<-def;d$layers[[1]]$raw_source$value[1]<-.9;bad(os_validate_figure_definition(d),"raw source mutation fails hash")
d<-def;d$statistics[[1]]$decision$q<-"not_below_threshold";bad(os_validate_figure_definition(d),"tampered missing decision refused")
d<-def;d$subset$ids<-list("alien");bad(os_validate_figure_definition(d),"subset outside eligible IDs refused")
# Exact Python->R source hash and complete canonical semantics (including sorted maps).
py<-file.path(here,"../py/tests/test_figure_semantics.py");f<-file.path(out,"python.json")
status<-system2("python",c(shQuote(py),"--fixture",shQuote(f)))
check(status==0,"Python synthetic fixture writer executed")
pd<-jsonlite::fromJSON(f,simplifyVector=FALSE)
check(isTRUE(os_validate_figure_definition(pd)),"Python definition validates in R")
rd<-os_normalize_figure_definition(def);os_write_json(rd,file.path(out,"r.json"),digits=I(17))
reread<-jsonlite::fromJSON(file.path(out,"r.json"),simplifyVector=FALSE)
check(isTRUE(os_validate_figure_definition(reread)),"R JSON roundtrip retains 17-digit raw values")
check(identical(rd$layers[[1]]$source_sha256,pd$layers[[1]]$source_sha256),"R/Python typed raw-table SHA256 exact")
# JSON parser normalization is the same on each path.
check(identical(.os_sort_keys(reread),.os_sort_keys(pd)),"R/Python complete canonical definition identical")
one<-data.frame(id="only",value=1/3)
ol<-os_semantic_layer("one",one,"id","model_grid","q","unknown")
od<-os_figure_definition("q","grid","unknown","unknown",list(status="unknown",rule="not supplied"),list(status="not_applicable",rule="all grid rows"),"none",list(ol))
os_write_json(os_normalize_figure_definition(od),file.path(out,"one.json"),digits=I(17))
check(isTRUE(os_validate_figure_definition(jsonlite::fromJSON(file.path(out,"one.json"),simplifyVector=FALSE))),"one-row source columns remain arrays and exact")
check(ol$n_observations==0&&is.null(ol$n_independent),"model grid does not manufacture observed/independent n")
nf<-data.frame(id=c("p","n","m"),value=c(Inf,-Inf,NA))
nd<-od;nd$layers<-list(os_semantic_layer("nf",nf,"id","reference","q","unknown"))
os_write_json(os_normalize_figure_definition(nd),file.path(out,"nf.json"),digits=I(17))
check(isTRUE(os_validate_figure_definition(jsonlite::fromJSON(file.path(out,"nf.json"),simplifyVector=FALSE))),"Inf/-Inf/NA survive JSON as distinct masks")
v<-nd;v$layers[[1]]$nonfinite_cells[[1]]$kind<-"negative_infinity";bad(os_validate_figure_definition(v),"nonfinite sign tamper fails")
u<-os_uncertainty("probability","CI","supplied Wald","pointwise","unknown","available",data.frame(source_id="a",lower=.1,estimate=.2,upper=1.05),.95,domain=c(0,1))
check(identical(unlist(u$out_of_domain_ids),"a")&&u$rows$upper==1.05,"probability interval outside domain flagged without clipping")
bad(os_uncertainty("q","CI","supplied","pointwise","unknown","available",u$rows),"CI level is never guessed")
bad(os_uncertainty("q","SD","supplied","distribution","unknown","available",u$rows,.95),"SD is not silently a95percentCI")
bad(os_uncertainty("q","CI","supplied","simultaneous_grid","unknown","available",u$rows,.95),"simultaneous interval needs joint source")
v<-u;v$rows$estimate<-2;bad(.os_validate_uncertainty(v,"a"),"source estimate outside interval remains a conflict")
u2<-u;u2$level<-.99;u2$rows$lower<-0;u2$rows$upper<-1.1
check(isTRUE(os_validate_nested_uncertainty(list(u2,u))),"nested masses reorder and validate explicit source bounds")
u2$rows$lower<-.15;bad(os_validate_nested_uncertainty(list(u,u2)),"larger mass narrower than smaller mass rejected")
cv<-matrix(c(1,.8,.8,1),2,dimnames=list(c("A","B"),c("A","B")))
joint<-os_contrast_joint_source("covariance",c("A","B"),c(A=1,B=-1),paste(rep("a",64),collapse=""),covariance=cv)
check(abs(joint$contrast_variance-.4)<1e-12&&!joint$interval_computed,"contrast uses covariance, not independent marginal endpoint subtraction")
bad(os_contrast_joint_source("marginal_CI",c("A","B"),c(A=1,B=-1),paste(rep("a",64),collapse="")),"marginal intervals are not joint uncertainty")
r<-os_semantic_ratio("localization",as.character(1:320),as.character(1:467),"people","people",320/467)
check(r$numerator$n==320&&r$denominator$n==467,"named ratio reconstructs full denominator")
bad(os_semantic_ratio("zero",character(),character(),"people","people",0),"zero denominator never becomes zero estimate")
check(is.na(os_semantic_ratio("zero",character(),character(),"people","people",NA_real_)$estimate),"undefined ratio is retained")
tr<-os_display_transform(c(.2,.8,0,-1),"log",invalid="missing")
check(identical(tr$raw,c(.2,.8,0,-1))&&sum(tr$state=="out_of_domain")==2,"display transform preserves zeros/negative raw values with states")
bad(os_analysis_values(tr),"display-only object cannot enter analysis")
bad(os_display_transform(1,"log",source_scale="log"),"double log refused")
bad(os_display_transform(1,"inverse_logit",source_scale="latent"),"latent score is not automatically probability")
check(os_display_transform(0,"exp",source_scale="log_link")$display==1,"Poisson log-link zero becomes response one")
tr<-os_display_transform(25000,"log",unit="seconds",ticks=25000,reference=1)
check(abs(tr$display-log(25000))<1e-14&&tr$ticks_display==tr$display&&tr$reference_display==0,"data/ticks/reference share exact transform")
check(all(os_display_transform(c(.5,2),"folded_ratio")$display==2),"folded ratio reciprocal symmetry does not imply direction")
bad(os_de_class(1,.01,.05,0,"local_fdr"),"local FDR cannot be silently adjusted P")
bad(os_p_label(.01,"t test",adjusted=FALSE,statistic_kind="qvalue"),"qvalue cannot be silently P label")
check(!grepl("= 0|10\\^",os_p_label(0,"t test",adjusted=FALSE)),"reported zero has unknown precision rather than fabricated bound")
b<-os_raw_p_decision_boundary(c(.001,.01,.2),c(.003,.015,.2),c("a","b","c"),3,.05)
check(b$cutoff==.01&&length(b$rejected_ids)==2,"raw P FDR line derives from complete supplied family")
bad(os_raw_p_decision_boundary(c(.01,.01),c(.01,.2),c("a","b"),2,.05),"tied raw P with conflicting decisions cannot be one FDR line")
check(!os_raw_p_decision_boundary(c(.2,.4),c(.4,.4),c("a","b"),2,.05)$boundary_available,"no rejection yields no invented FDR line")
cmp<-data.frame(comparison_id=c("c1","c2"),group1=c("A","B"),group2=c("B","C"),p=c(.053,NA),y=c(3,3.5),
 test=c("Welch t","paired t"),adjustment=c("none","BH"),family_size=c(2,2),statistic_kind=c("raw_p","adjusted_p"),
 model_id=c("m1","m2"),endpoint="response",family_id=c("f1","f2"),paired_unit=c("not_applicable","people"),source_result_id=c("r1","r2"),comparison_type="pairwise")
cl<-os_comparison_labels(cmp,c("A","B","C"))
check(grepl("Welch t",cl$caption[1])&&grepl("paired t",cl$caption[2])&&cl$state[2]=="unavailable","per-comparison tests and missing state preserved")
cc<-cmp;cc$comparison_type[1]<-"omnibus";bad(os_comparison_labels(cc,c("A","B","C")),"omnibus test cannot attach to pairwise bracket")
cc<-cmp;cc$raw_p<-c(.01,NA);bad(os_comparison_labels(cc,c("A","B","C")),"printed P must equal selected unrounded source result")
enc<-os_category_encodings(c("1","3","8"),"cells","run_cluster",run_id="runA")
enc2<-os_category_encodings(c("1","3","8","9"),"cells","run_cluster",enc$registry,"runA")
check(identical(enc$shape,enc2$shape[unlist(enc$ids)])&&identical(enc$colour,enc2$colour[unlist(enc$ids)]),"category registry preserves old shape/colour when new category appears")
other<-os_category_encodings(c("1","3"),"cells","run_cluster",enc$registry,"runB")
check(enc$registry_key!=other$registry_key&&other$equivalence_claim=="within_declared_run_only","same cluster number in another run is not equivalent")
bad(os_category_encodings(c("a","b"),"class","biological_class",legend_ids="a"),"legend omissions refused")
p1<-data.frame(id=c("a","b","c","d"),cluster=c("1","1","2",NA));p2<-data.frame(id=c("d","c","b","a","new"),cluster=c(NA,"x","y","y","z"))
ov<-os_category_overlap(p1,p2,"id","cluster","cluster","A","B")
check(sum(ov$table$n_intersection)==4&&ov$n_new==1&&ov$n_common==4,"partition overlap keyed and missing preserved, many-to-many table reconciles")
check(all(abs(tapply(ov$table$row_fraction,ov$table$reference,sum)-1)<1e-12),"row fractions use reference denominator")
em<-data.frame(x=1:5,y=c(0,1,0,1,2),group=c("A","A","B",NA,"B"))
e<-os_embedding(em,"group",label=FALSE,category_namespace="test",category_role="biological_class",redundant_shapes=TRUE)
me<-attr(e,"os_meta")
check(sum(unlist(me$counts))==5&&me$notes$missing_metadata_n==1&&me$encodings$shape[["Missing metadata"]]==4,"missing embedding metadata counted and visible as grey cross")
check(all(os_figure_glyph_audit("\u03c3\u2081 \u03b1 \u2212")$available),"actual font has Greek/minus/subscript glyphs")
check(abs(os_text_contrast_ratio("black","white")-21)<1e-12,"physical text contrast21to1 black/white")
low<-ggplot2::ggplot(data.frame(x=1,y=1),ggplot2::aes(x,y))+ggplot2::geom_label(label="text",colour="#EEEEEE",fill="white")
check("FIG-TEXT-CONTRAST" %in% os_fig_lint(low)$rule,"low text contrast linted")
pg<-os_figure_pages(paste0("r",1:11),80,10,20,10)
check(pg$n_pages==3&&identical(unlist(pg$pages,use.names=FALSE),paste0("r",1:11))&&pg$repeated_headers,"physical pagination retains all IDs and repeated headers")
vw<-os_figure_view(c("a","b","c","d"),c(-2,0,5,NA),c(-1,1))
check(vw$n_visible+vw$n_excluded_view+vw$n_unavailable==vw$n_total&&identical(vw$full_values,c(-2,0,5,NA)),"viewport exclusions reconcile and raw values remain")
budget<-os_layout_budget(c("A","B","C"),80,60,3,label_ids=c("x","y"),shown_label_ids="x")
check(budget$crowded&&identical(unlist(budget$suppressed_label_ids),"y")&&budget$suppressed_observations==0,"label budget never deletes observations")
check(isTRUE(os_validate_evidence_refs(os_figure_evidence("group_comparison"))),"existing pending evidence refs remain valid")

# Typed render binding prevents a valid but unrelated source table on a plot.
check(os_validate_render_sources(def,list(df=raw))$status=="exact_source_hash_and_keys","renderer binds exact retained source table")
wrong<-raw;wrong$value[1]<-.9;bad(os_validate_render_sources(def,list(df=wrong)),"unrelated render data rejected before plotting")
transformed<-raw;transformed$value<-c(.2,.3,NA)
tl<-os_semantic_layer("t",transformed,"id","observed","q","unknown",transform=os_layer_transform(transformed,"value",kind="log",invalid="missing"))
td<-od;td$layers<-list(tl)
os_write_json(os_normalize_figure_definition(td),file.path(out,"transform.json"),digits=I(17))
check(isTRUE(os_validate_figure_definition(jsonlite::fromJSON(file.path(out,"transform.json"),simplifyVector=FALSE))),"typed transform replays through JSON without dropping missing slot")
td$layers[[1]]$transform$operation$display[1]<-999;bad(os_validate_figure_definition(td),"forged display value rejected")
ft<-data.frame(feature_id=c("g1","g2","g3"),log2fc=c(-2,0,2),padj=c(.01,.1,.03),q=c(.01,.1,.03),raw_p=c(.01,.1,.03))
qp<-os_volcano(ft,statistic_kind="qvalue",statistic_col="q")
rp<-os_volcano(ft,statistic_kind="raw_p",statistic_col="raw_p",adjustment="none")
check(grepl("q value",qp$labels$y)&&grepl("unadjusted P",rp$labels$y),"identical numbers in different statistic types yield distinct actual axes")
bad(os_volcano(ft,statistic_kind="qvalue"),"padj cannot be renamed q value implicitly")
bad(os_volcano(ft,statistic_kind="local_fdr"),"unsupported local FDR volcano fails explicitly")


std<-os_fixed_standardization(c(-2,0,2,4),0,2,c("baseline1","baseline2"),paste(rep("a",64),collapse=""),"raw score")
check(identical(std$display,c(-1,0,1,2))&&identical(std$inverse_check,c(-2,0,2,4)),"fixed baseline SD is reversible across visits, negatives retained")
bad(os_fixed_standardization(1:2,0,c(1,2),c("a","b"),paste(rep("a",64),collapse=""),"score"),"visit-specific SD vector cannot masquerade as fixed reference")
qr<-os_quantity_ratio(c(100,-100,1),c(2,-2,0),c("a","b","c"),"EUR","unit","increment ratio")
check(qr$estimate[1]==50&&is.na(qr$estimate[3])&&qr$denominator_crosses_zero&&!qr$summary_ratio_inferred,"increment ratio preserves numerator direction, zero denominator and cross-zero state")


vv<-def;vv$layers[[2]]<-vv$layers[[1]];vv$layers[[2]]$id<-"conflict";vv$layers[[2]]$independent_ids$z<-"other";vv$layers[[2]]$n_independent<-3
bad(os_validate_figure_definition(vv),"same population observation cannot map to another person")
ss<-data.frame(source_id=raw$id,state=c("true_zero","observed","missing"),reason="supplied",source_column="value")
bad(os_semantic_layer("badzero",raw,"id","observed","q","unknown",states=ss),"true-zero tag cannot relabel nonzero raw source")
rr<-raw;rr$value[1]<-0
check(is.list(os_semantic_layer("zero",rr,"id","observed","q","unknown",states=ss)),"true-zero tag resolves actual zero source value")
sim<-os_uncertainty("q","CI","supplied joint fixture","simultaneous_grid","people","available",data.frame(source_id="a",lower=.1,estimate=.2,upper=.4),.95,joint_source=joint)
os_write_json(sim,file.path(out,"joint.json"),digits=I(17))
sim2<-jsonlite::fromJSON(file.path(out,"joint.json"),simplifyVector=FALSE);sim2$rows<-.os_sem_frame(sim2$rows)
check(isTRUE(.os_validate_uncertainty(sim2,"a")),"supplied joint source validates across JSON")
sim2$joint_source<-list(kind="because_supplied");bad(.os_validate_uncertainty(sim2,"a"),"bogus joint provenance cannot declare simultaneous coverage")


bad(os_semantic_layer("prob",data.frame(id="a",value=1.2),"id","observed","probability","fraction",value_columns="value"),"explicit probability field is bounded without clipping")
check(is.list(os_semantic_layer("latent",data.frame(id="a",value=-2),"id","model_grid","latent score","unknown",value_columns="value")),"signed latent score is not forced into probability bounds")

# Repeated metadata attachment must preserve explicit nullable typed fields.
base_plot<-ggplot2::ggplot(raw,ggplot2::aes(id,value))+ggplot2::geom_point()
typed_plot<-os_with_meta(base_plot,definition=def,notes=list(existing="kept"))
typed_again<-os_with_meta(typed_plot,definition=def,notes=list(extra="new"))
check(identical(attr(typed_plot,"os_meta")$definition,attr(typed_again,"os_meta")$definition)&&
      all(c("numerator","denominator") %in% names(attr(typed_again,"os_meta")$definition)),"repeated typed attachment preserves explicit null numerator and denominator")
check(attr(typed_again,"os_meta")$notes$existing=="kept"&&attr(typed_again,"os_meta")$notes$extra=="new","ordinary metadata retains recursive merge compatibility")
with_notes<-def;with_notes$notes<-list(previous="must disappear")
cleared<-os_with_meta(os_with_meta(base_plot,definition=with_notes),definition=def)
check(identical(attr(cleared,"os_meta")$definition,attr(typed_plot,"os_meta")$definition),"complete typed replacement never inherits stale nested fields")
saved<-os_save_figure(typed_plot,file.path(out,"extra-meta"),formats=character(),extra_meta=list(definition=def,notes=list(extra="new")))
saved_json<-jsonlite::fromJSON(saved$spec,simplifyVector=FALSE)
check(identical(.os_sort_keys(saved_json$definition),.os_sort_keys(reread))&&
      all(c("numerator","denominator") %in% names(saved_json$definition)),"extra_meta repeated typed definition has exact null-preserving JSON replay")
bad(os_with_meta(typed_plot,definition=NULL),"typed metadata cannot be erased by attachment")
bad(os_with_meta(typed_plot,definition=list(quantity="patched")),"partial typed metadata replacement refused")
bad(os_save_figure(typed_plot,file.path(out,"erased"),formats=character(),extra_meta=list(definition=NULL)),"extra_meta cannot erase typed definition")
bad(os_save_figure(typed_plot,file.path(out,"partial"),formats=character(),extra_meta=list(definition=list(semantic_version=OS_FIG_SEMANTIC_VERSION))),"extra_meta incomplete typed definition refused")
# Delimiter-containing labels must not alias a different namespace/run tuple.
collision_a<-os_category_encodings("one","a","run_cluster",run_id="b::run_cluster::c")
collision_b<-os_category_encodings("two","a::run_cluster::b","run_cluster",collision_a$registry,run_id="c")
check(collision_a$registry_key!=collision_b$registry_key&&length(collision_b$registry$families)==2,"category namespace keys use collision-free JSON tuples")
ce<-me$notes$category_encoding;key<-ce$registry_key;missing_name<-"Missing metadata"
check(identical(ce$colour[[missing_name]],OS_FIG$col_reference_group)&&identical(ce$shape[[missing_name]],4L)&&
      identical(ce$registry,me$colour_registry)&&identical(unname(me$colour_registry$families[[key]][missing_name]),OS_FIG$col_reference_group)&&
      identical(me$colour_registry$styles[[key]]$shape[[missing_name]],4L),"missing glyph agrees across scale, category metadata and registry")
check(os_text_contrast_ratio(me$encodings$colour[[missing_name]],OS_FIG$col_bg)>=4.5,"missing cross uses dark-grey contrast of at least4.5to1")
built<-ggplot2::ggplot_build(e)$data[[1]]
check(sum(built$shape==4L & built$colour==OS_FIG$col_reference_group)==1L,"actual drawn missing glyph has recorded dark-grey cross encoding")
os_colour_registry_write(me$colour_registry,file.path(out,"encoding-registry.json"))
round_registry<-os_colour_registry_read(file.path(out,"encoding-registry.json"))
round_encoding<-os_category_encodings(c("A","B",missing_name),"test","biological_class",round_registry)
check(identical(round_encoding$colour,ce$colour)&&identical(round_encoding$shape,ce$shape)&&identical(round_encoding$linetype,ce$linetype),"colour shape and line mappings persist through registry JSON")
legacy_missing<-attr(os_embedding(em,"group",label=FALSE),"os_meta")
check(identical(unname(legacy_missing$colour_registry$families$group[missing_name]),OS_FIG$col_reference_group),"non-namespaced returned registry also records actual missing colour")

if(length(failures)) {cat(length(failures),"of",checks,"CHECKS FAILED\n");quit(status=1)}
cat("ALL",checks,"SEMANTIC CHECKS PASSED\n")
